namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings == 0 ? 0 : (double)RatingSum / TotalRatings;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F.", "Roll out dough on floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute.", "Bake 10-12 minutes until crust is golden.", "Top with fresh basil and drizzle olive oil."],
                TotalRatings = 12, RatingSum = 50
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Garlic", "Ginger", "Cumin"],
                Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-sear chicken until charred.", "Sauté garlic and ginger in oil.", "Add tomato sauce and simmer 10 minutes.", "Stir in cream and spices.", "Add chicken and simmer 5 more minutes."],
                TotalRatings = 8, RatingSum = 35
            },
            new Recipe
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning"],
                Steps = ["Brown beef in a skillet over medium heat.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in oven.", "Assemble with beef, lettuce, tomato, cheese.", "Top with sour cream and serve."],
                TotalRatings = 15, RatingSum = 60
            },
            new Recipe
            {
                Id = 4, Title = "Pad Thai", Category = "Thai",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Lime", "Fish sauce", "Tamarind paste", "Sugar"],
                Steps = ["Soak rice noodles in warm water 30 minutes.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in wok.", "Add noodles, fish sauce, tamarind, and sugar.", "Toss with shrimp and bean sprouts.", "Serve with crushed peanuts and lime wedge."],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F. Grease ramekins.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla.", "Fold chocolate mixture into eggs.", "Add flour and stir until just combined.", "Bake 12-14 minutes until edges are set but center jiggles."],
                TotalRatings = 20, RatingSum = 92
            },
            new Recipe
            {
                Id = 6, Title = "Caesar Salad", Category = "Salads",
                Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Caesar dressing", "Lemon juice", "Anchovy paste"],
                Steps = ["Wash and chop romaine lettuce.", "Make dressing: whisk anchovy paste, lemon, and Caesar dressing.", "Toss lettuce with dressing.", "Top with shaved Parmesan and croutons.", "Serve immediately."],
                TotalRatings = 5, RatingSum = 19
            }
        ];
        _nextId = 7;
    }

    public List<RecipeCategory> GetCategories()
    {
        return
        [
            new RecipeCategory { Name = "Italian", Description = "Pasta, pizza, and Mediterranean flavors", Icon = "🍕" },
            new RecipeCategory { Name = "Indian", Description = "Rich curries and aromatic spices", Icon = "🍛" },
            new RecipeCategory { Name = "Mexican", Description = "Bold flavors with chilies and lime", Icon = "🌮" },
            new RecipeCategory { Name = "Thai", Description = "Sweet, sour, salty, and spicy balance", Icon = "🍜" },
            new RecipeCategory { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" },
            new RecipeCategory { Name = "Salads", Description = "Fresh and healthy greens", Icon = "🥗" }
        ];
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(string title, string category, List<string> ingredients, List<string> steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

